    cast(un_order_bands.drink_item_lines as decimal(15,0)) as drink_item_lines,
    cast(un_order_bands.food_share_of_lines as decimal(10,4)) as food_share_of_lines,  -- FLAG rounds L2494: FOOD_SHARE_OF_LINES is computed as IIF(v_ITEM_LINES_CL = 0, 0, v_FOOD_ITEM_LINES_CL / v_ITEM_LINES_CL) (L1617), a double at run time because high precision is off, and is rounded to 4 decimal places by the target column FOOD_SHARE_OF_LINES decimal(10,4) (decision Q11)
    cast(un_order_bands.drink_share_of_lines as decimal(10,4)) as drink_share_of_lines,  -- FLAG rounds L2495: DRINK_SHARE_OF_LINES is computed as IIF(v_ITEM_LINES_CL = 0, 0, v_DRINK_ITEM_LINES_CL / v_ITEM_LINES_CL) (L1618), a double at run time because high precision is off, and is rounded to 4 decimal places by the target column DRINK_SHARE_OF_LINES decimal(10,4) (decision Q11)
